public class ObjectReader__verifySchemaType_TriageGen1Test {

    private ObjectReader objectReader;

    @Mock
    private ObjectMapper mapper;

    @Mock
    private DeserializationConfig config;

    @Mock
    private FormatSchema mockSchema;

    @Mock
    private JsonFactoryInterface parserFactory;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // Use the protected constructor via reflection or a public entry point
        // Since we need to inject the parserFactory which is a private field in ObjectReader, 
        // we will use reflection to set it.
        objectReader = new ObjectReader(mapper, config);

        // Inject the parserFactory into the objectReader instance
        // In Jackson, _parserFactory is usually a field within ObjectReader or its base
        Field factoryField = ObjectReader.class.getDeclaredField("_parserFactory");
        factoryField.setAccessible(true);
        factoryField.set(objectReader, parserFactory);
    }

    /**
     * Helper to invoke the protected method _verifySchemaType
     */
    private void invokeVerifySchemaType(FormatSchema schema) throws Exception {
        Method method = ObjectReader.class.getDeclaredMethod("_verifySchemaType", FormatSchema.class);
        method.setAccessible(true);
        try {
            method.invoke(objectReader, schema);
        } catch (java.lang.reflect.InvocationTargetException e) {
            // Unwrap the actual exception thrown by the method
            throw (Exception) e.getCause();
        }
    }

    @Test
    public void testVerifySchemaType_nullSchema_doesNothing() throws Exception {
        // Branch: if (schema != null) -> false
        invokeVerifySchemaType(null);
        // Success if no exception thrown
    }

    @Test
    public void testVerifySchemaType_validSchema_doesNothing() throws Exception {
        // Branch: if (schema != null) -> true, if (!_parserFactory.canUseSchema(schema)) -> false
        when(parserFactory.canUseSchema(mockSchema)).thenReturn(true);

        invokeVerifySchemaType(mockSchema);

        verify(parserFactory, times(1)).canUseSchema(mockSchema);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testVerifySchemaType_invalidSchema_throwsException() throws Exception {
        // Branch: if (schema != null) -> true, if (!_parserFactory.canUseSchema(schema)) -> true
        when(parserFactory.canUseSchema(mockSchema)).thenReturn(false);
        when(parserFactory.getFormatName()).thenReturn("test-format");

        try {
            invokeVerifySchemaType(mockSchema);
        } catch (IllegalArgumentException e) {
            // Verify the error message contains expected details
            assert(e.getMessage().contains("Can not use FormatSchema of type"));
            assert(e.getMessage().contains("test-format"));
            throw e;
        }
    }
}
